    "PAYHOOK_TIMEOUT": "10",
    "PAYHOOK_REGION": "eu",
}

# Settings whose values must never be shown in full (support tickets, logs).
SECRET_KEYS = frozenset({"PAYHOOK_API_TOKEN", "PAYHOOK_WEBHOOK_SECRET"})


def _parse_line(line):
    """Parse one dotenv line into (key, value), or None if it is not an assignment.

    Supports ``KEY=value``, ``export KEY=value``, single- or double-quoted
    values, and ``=`` characters inside the value. Unquoted values may be
    followed by a ``# comment``.
    """
    line = line.strip()
    if not line or line.startswith("#"):
        return None
    if line.startswith("export ") or line.startswith("export\t"):
        line = line[len("export"):].lstrip()
    if "=" not in line:
        return None
    key, value = line.split("=", 1)
    key = key.strip()
    if not key:
        return None
    value = value.strip()
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        value = value[1:-1]
    else:
        # Unquoted: drop a trailing inline comment ("value  # note").
        for marker in (" #", "\t#"):
            if marker in value:
                value = value.split(marker, 1)[0].rstrip()
    return key, value


def read_dotenv(path):
    values = {}
    if not os.path.exists(path):
        return values
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            parsed = _parse_line(line)
            if parsed is not None:
                values[parsed[0]] = parsed[1]
    return values


def load_config(environ=None, dotenv_path=".env"):
    environ = os.environ if environ is None else environ
    dotenv = read_dotenv(dotenv_path)
    config = {}
    for key, default in DEFAULTS.items():
        if key in environ:
            config[key] = (environ[key], "env")
        elif key in dotenv:
            config[key] = (dotenv[key], ".env")
        else:
            config[key] = (default, "default")
    return config


def redact(key, value):
    """Return a display-safe form of a setting value."""
    if value is None:
        return "(not set)"
    if key in SECRET_KEYS:
        if len(value) <= 8:
            return "****"
        return value[:4] + "****" + value[-4:]
    return value


def doctor_report(environ=None, dotenv_path=".env"):
    """Build the lines printed by ``python -m payhook doctor``."""
    config = load_config(environ=environ, dotenv_path=dotenv_path)
    dotenv_abs = os.path.abspath(dotenv_path)
    lines = ["payhook doctor"]
    if os.path.exists(dotenv_path):
        lines.append(".env file: " + dotenv_abs)
    else:
        lines.append(".env file: " + dotenv_abs + " (not found)")
    lines.append("")
    width = max(len(k) for k in config)
    for key, (value, source) in config.items():
        lines.append("%-*s  %-8s  %s" % (width, key, source, redact(key, value)))
    lines.append("")
    lines.append("sources: env = process environment, .env = dotenv file, default = built-in")
    lines.append("secret values are shown redacted; do not paste full secrets into tickets")
    return lines

